const toast=document.getElementById('toast');let timer;function notify(message){clearTimeout(timer);toast.textContent=message;toast.hidden=false;timer=setTimeout(()=>toast.hidden=true,6000)}document.querySelectorAll('[data-app]').forEach(button=>button.addEventListener('click',async()=>{button.disabled=true;try{const response=await fetch('/api/launch/'+button.dataset.app,{method:'POST',headers:{'Content-Type':'application/json'}});const result=await response.json();if(!response.ok)throw new Error(result.error||'启动失败');notify(result.message)}catch(error){notify('无法启动：'+error.message+'。请通过本地首页启动器打开页面。')}finally{button.disabled=false}}));
